"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Browser SpeechRecognition wrapper. Renders a mic toggle button that
 * starts/stops the Web Speech API and emits transcript chunks.
 *
 * Headless on data: `isListening` + `onListeningChange` are required so
 * the consumer keeps state where it fits (a `useChat` hook, redux,
 * local state). `onTranscript` fires per result with `isFinal` so the
 * consumer can append finalized phrases and replace interim ones.
 *
 * Falls back to a disabled button labeled `notSupportedLabel` when the
 * browser lacks `SpeechRecognition` (Firefox as of 2026, older Safari).
 *
 * @example
 * const [listening, setListening] = useState(false);
 * const [text, setText] = useState("");
 * <SpeechRecognition
 *   isListening={listening}
 *   onListeningChange={setListening}
 *   onTranscript={(chunk, isFinal) => {
 *     if (isFinal) setText((t) => t + chunk);
 *   }}
 * />
 */
type SpeechRecognitionConstructor = new () => SpeechRecognitionInstance;

interface SpeechRecognitionResultLike {
	readonly isFinal: boolean;
	readonly length: number;
	readonly [index: number]: { readonly transcript: string };
}

interface SpeechRecognitionResultListLike {
	readonly length: number;
	readonly [index: number]: SpeechRecognitionResultLike;
}

interface SpeechRecognitionEventLike {
	readonly resultIndex: number;
	readonly results: SpeechRecognitionResultListLike;
}

interface SpeechRecognitionErrorEventLike {
	readonly error: string;
	readonly message?: string;
}

interface SpeechRecognitionInstance {
	continuous: boolean;
	interimResults: boolean;
	lang: string;
	onresult: ((event: SpeechRecognitionEventLike) => void) | null;
	onerror: ((event: SpeechRecognitionErrorEventLike) => void) | null;
	onend: (() => void) | null;
	start(): void;
	stop(): void;
	abort(): void;
}

/*
 * The Web Speech API is not in TypeScript's DOM lib, and Chromium still
 * only exposes the vendor-prefixed name. Declaring both on `Window` types
 * the access directly instead of casting `window` at each call site.
 */
declare global {
	interface Window {
		SpeechRecognition?: SpeechRecognitionConstructor;
		webkitSpeechRecognition?: SpeechRecognitionConstructor;
	}
}

function getSpeechRecognitionCtor(): SpeechRecognitionConstructor | null {
	if (typeof window === "undefined") return null;
	return window.SpeechRecognition ?? window.webkitSpeechRecognition ?? null;
}

export interface SpeechRecognitionProps
	extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onError"> {
	/** Controlled listening state. */
	isListening: boolean;
	/** Called when listening starts/stops (user toggle or browser auto-end). */
	onListeningChange: (listening: boolean) => void;
	/** Called per transcript chunk. `isFinal` indicates a finalized phrase. */
	onTranscript: (text: string, isFinal: boolean) => void;
	/** Called on browser error (e.g. "not-allowed", "no-speech", "network"). */
	onError?: (error: string, message?: string) => void;
	/** BCP-47 language tag. Default `"en-US"`. */
	lang?: string;
	/** Keep listening across pauses. Default `true`. */
	continuous?: boolean;
	/** Emit interim (in-progress) results. Default `true`. */
	interimResults?: boolean;
	/** Accessible name when idle. Default `"Start dictation"`. */
	startLabel?: string;
	/** Accessible name when listening. Default `"Stop dictation"`. */
	stopLabel?: string;
	/** Accessible name + tooltip when the browser lacks the API. */
	notSupportedLabel?: string;
}

/**
 * Renders a mic toggle button wired to the Web Speech API.
 * @param props - controlled listening state + transcript callback
 * @returns A button element that toggles speech recognition
 */
function SpeechRecognition({
	isListening,
	onListeningChange,
	onTranscript,
	onError,
	lang = "en-US",
	continuous = true,
	interimResults = true,
	startLabel = "Start dictation",
	stopLabel = "Stop dictation",
	notSupportedLabel = "Speech recognition not supported in this browser",
	disabled,
	className,
	...rest
}: SpeechRecognitionProps) {
	const recognitionRef = React.useRef<SpeechRecognitionInstance | null>(null);
	const [isSupported, setIsSupported] = React.useState(true);

	// "Latest ref" pattern, assigned synchronously in render so a Web Speech
	// callback firing between commit and a useEffect can never see stale
	// closures. React permits ref mutation during render when the assignment
	// is purely a latest-value mirror.
	const onTranscriptRef = React.useRef(onTranscript);
	const onListeningChangeRef = React.useRef(onListeningChange);
	const onErrorRef = React.useRef(onError);
	onTranscriptRef.current = onTranscript;
	onListeningChangeRef.current = onListeningChange;
	onErrorRef.current = onError;

	// Mounted guard: the engine fires onend asynchronously, sometimes after
	// the React tree has been torn down. Without this, a stale handler can
	// invoke setState on an unmounted parent.
	const mountedRef = React.useRef(true);
	React.useEffect(
		() => () => {
			mountedRef.current = false;
		},
		[],
	);

	// Set when the lifecycle effect's cleanup runs because of a prop change
	// (lang/continuous/interimResults), not user-initiated stop. The about-
	// to-fire onend should NOT bubble back as `onListeningChange(false)` in
	// that case — the new effect run is about to re-create the engine.
	const rebuildingRef = React.useRef(false);
	// Latest `isListening` mirror so cleanup can read the NEW value (closure
	// captures OLD). NEW=true means this is a prop-change rebuild; NEW=false
	// means the user stopped.
	const isListeningRef = React.useRef(isListening);
	isListeningRef.current = isListening;

	// SSR: ctor lookup must run after mount.
	React.useEffect(() => {
		const Ctor = getSpeechRecognitionCtor();
		setIsSupported(Ctor !== null);
	}, []);

	// Toggle the engine on `isListening` change. Recreate per session so a
	// stuck session can't leak — Chrome's recognition is single-use after
	// onend in some failure modes.
	React.useEffect(() => {
		if (!isListening) return;

		const Ctor = getSpeechRecognitionCtor();
		if (!Ctor) return;

		const instance = new Ctor();
		instance.continuous = continuous;
		instance.interimResults = interimResults;
		instance.lang = lang;

		instance.onresult = (event) => {
			if (!mountedRef.current) return;
			for (let i = event.resultIndex; i < event.results.length; i++) {
				const result = event.results[i];
				const transcript = result[0]?.transcript ?? "";
				if (transcript) onTranscriptRef.current(transcript, result.isFinal);
			}
		};
		instance.onerror = (event) => {
			if (!mountedRef.current) return;
			onErrorRef.current?.(event.error, event.message);
			// "aborted" is a normal stop signal — don't toggle off twice.
			if (event.error !== "aborted") onListeningChangeRef.current(false);
		};
		instance.onend = () => {
			if (!mountedRef.current) return;
			// Skip the off-toggle when cleanup is from a prop-change rebuild;
			// the next effect run will re-start with the new options.
			if (rebuildingRef.current) return;
			onListeningChangeRef.current(false);
		};

		recognitionRef.current = instance;
		try {
			instance.start();
		} catch (err) {
			// Chrome throws if start() is called twice; surface as an error
			// rather than letting it crash the React tree.
			onErrorRef.current?.("start-failed", err instanceof Error ? err.message : String(err));
			onListeningChangeRef.current(false);
		}

		return () => {
			// Mark this teardown as a rebuild iff isListening is STILL true
			// in the latest render (only lang/continuous/interimResults
			// changed). On a real user-stop the NEW isListening is false and
			// any synchronous onend-from-abort should toggle parent state.
			rebuildingRef.current = isListeningRef.current;
			instance.onresult = null;
			instance.onerror = null;
			instance.onend = null;
			try {
				instance.abort();
			} catch {
				// abort() throws if the engine never started; safe to ignore.
			}
			recognitionRef.current = null;
			// Reset on next microtask so a follow-up effect run sees a clean slate.
			queueMicrotask(() => {
				rebuildingRef.current = false;
			});
		};
	}, [isListening, continuous, interimResults, lang]);

	const tooltip = !isSupported
		? notSupportedLabel
		: isListening
			? stopLabel
			: startLabel;
	// aria-label is stable when supported so screen readers don't re-announce
	// the entire button on each toggle. State is conveyed via aria-pressed.
	// Only the unsupported case swaps the accessible name.
	const accessibleName = isSupported ? startLabel : notSupportedLabel;
	const isDisabled = disabled || !isSupported;

	return (
		<button
			type="button"
			{...rest}
			disabled={isDisabled}
			aria-label={accessibleName}
			aria-pressed={isListening}
			title={tooltip}
			onClick={(event) => {
				rest.onClick?.(event);
				if (event.defaultPrevented || isDisabled) return;
				onListeningChange(!isListening);
			}}
			className={cn(
				"inline-flex h-9 w-9 items-center justify-center rounded-md border bg-background",
				"text-foreground transition-all duration-[var(--duration-normal,200ms)] ease-out",
				"hover:bg-accent hover:text-accent-foreground",
				"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
				"disabled:cursor-not-allowed disabled:opacity-50",
				isListening && "animate-pulse border-destructive text-destructive",
				className,
			)}
		>
			<svg
				aria-hidden
				viewBox="0 0 16 16"
				width="14"
				height="14"
				fill="none"
				stroke="currentColor"
				strokeWidth="1.5"
				strokeLinecap="round"
				strokeLinejoin="round"
			>
				<rect x="6" y="2" width="4" height="8" rx="2" />
				<path d="M3.5 7.5a4.5 4.5 0 0 0 9 0" />
				<path d="M8 12v2" />
				<path d="M5.5 14h5" />
			</svg>
		</button>
	);
}

export { SpeechRecognition };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}

